export function settingsMotion(initial){let value={angle:initial.angle,index:initial.index,height:initial.height},target={...value},from={...value},elapsed=1,duration=.8,key=initial.runId;return {get value(){return value;},get active(){return elapsed<duration;},get changed(){return Object.keys(target).filter(k=>Math.abs(target[k]-from[k])>.0001);},update(next,dt,enabled=true){if(!enabled||key!==next.runId){key=next.runId;value={angle:next.angle,index:next.index,height:next.height};target={...value};from={...value};elapsed=duration;return;}if(['angle','index','height'].some(k=>next[k]!==target[k])){from={...value};target={angle:next.angle,index:next.index,height:next.height};elapsed=0;duration=.7;}elapsed=Math.min(duration,elapsed+Math.min(.08,Math.max(0,dt)));const u=elapsed/duration,e=u*u*(3-2*u);for(const k of ['angle','height'])value[k]=from[k]+(target[k]-from[k])*e;const delta=((target.index-from.index+144)%96)-48;value.index=u===1?target.index:from.index+delta*e;}};}
